/* Copy the entry at `index` of the table. */
bool its_trustlist_at(size_t index, its_trust_entry_t *out)
{
    if (index >= ITS_TRUSTLIST_COUNT)
        return false;
    if (out)
        *out = s_entries[index];
    return true;
}

static const its_trust_entry_t *search_sha256(const uint8_t id8[8])
{
    size_t lo = 0;
    size_t hi = ITS_TRUSTLIST_COUNT;
    while (lo < hi)
    {
        size_t mid = lo + (hi - lo) / 2;
        int c = memcmp(id8, s_entries[mid].id8_sha256, 8);
        if (c == 0)
            return &s_entries[mid];
        if (c < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    return NULL;
}

static const its_trust_entry_t *search_sha384(const uint8_t id8[8])
{
    size_t lo = 0;
    size_t hi = ITS_TRUSTLIST_COUNT;
    while (lo < hi)
    {
        size_t mid = lo + (hi - lo) / 2;
        const its_trust_entry_t *e = &s_entries[s_by_sha384[mid]];
        int c = memcmp(id8, e->id8_sha384, 8);
        if (c == 0)
            return e;
        if (c < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    return NULL;
}

bool its_trustlist_find_alg(const uint8_t id8[8], uint8_t alg, its_trust_entry_t *out)
{
    if (!id8)
        return false;
    const its_trust_entry_t *e = NULL;
    if (alg == ITS_TRUST_HASH_SHA256)
        e = search_sha256(id8);
    else if (alg == ITS_TRUST_HASH_SHA384)
        e = search_sha384(id8);
    if (!e)
        return false;
    if (out)
        *out = *e;
    return true;
}

bool its_trustlist_find(const uint8_t id8[8], its_trust_entry_t *out)
{
    if (!id8)
        return false;
    const its_trust_entry_t *e = search_sha256(id8);
    if (!e)
        e = search_sha384(id8);
    if (!e)
        return false;
    if (out)
        *out = *e;
    return true;
}

size_t its_trustlist_count(void)
{
    return ITS_TRUSTLIST_COUNT;
}

const its_trust_list_t *its_trustlist_list(uint8_t env)
{
    if (env >= ITS_TRUST_ENV_COUNT)
        return NULL;
    return &s_lists[env];
}

const char *its_trustlist_env_name(uint8_t env)
{
    static const char *const names[ITS_TRUST_ENV_COUNT] = { "L0", "L1", "L2" };
    return env < ITS_TRUST_ENV_COUNT ? names[env] : "?";
}

/* The certificate bytes plus the table, its index and the list headers. The names are
 * left out because the compiler pools the ones that repeat. */
size_t its_trustlist_flash_bytes(void)
{
    return ITS_TRUSTLIST_CERT_BYTES + sizeof s_entries + sizeof s_by_sha384
           + sizeof s_lists;
}
